from docx import Document
p='/mnt/data/GMRI_ADA_OpenAI.docx'
d=Document(p)
for i,para in enumerate(d.paragraphs):
    if any(w in para.text.lower() for w in ['dots feature','business premium','hour','income','pricing']):
        print(i,para.style.name,repr(para.text), 'runs',len(para.runs))
        for j,r in enumerate(para.runs): print('  ',j,repr(r.text),r.bold,r.italic)
print('num paras',len(d.paragraphs))
